import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@3.4.0";
import { z as z3 } from "npm:zod@^3.25.76";
var STATUSES = [
  "Not submitted",
  "Submitted",
  "Partially reimbursed",
  "Fully reimbursed"
];
var list_expenses_default = defineTool3({
  name: "list_expenses",
  title: "List expenses",
  description: "List the signed-in user's expenses, newest first. Filter by trip or reimbursement status \u2014 useful for seeing what is still pending reimbursement.",
  inputSchema: {
    trip_id: z3.string().uuid().optional().describe("Only show expenses for this trip (from list_trips)."),
    reimbursed_status: z3.enum(STATUSES).optional().describe("Only show expenses with this reimbursement status."),
    limit: z3.number().int().min(1).max(100).optional().describe("Maximum number of expenses to return (default 25, max 100).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true },
  handler: async ({ trip_id, reimbursed_status, limit }, ctx) => {
    const supabase = supabaseForUser(ctx);
    let query = supabase.from("expenses").select("*").order("date", { ascending: false }).limit(limit ?? 25);
    if (trip_id) query = query.eq("trip_id", trip_id);
    if (reimbursed_status) query = query.eq("reimbursed_status", reimbursed_status);
    const { data, error } = await query;
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    const expenses = (data ?? []).map((e) => ({
      expense_id: e.expense_id,
      trip_id: e.trip_id,
      date: e.date,
      merchant: e.merchant,
      category: e.category,
      description: e.description,
      amount: e.amount,
      currency: e.currency,
      payment_method: e.payment_method,
      reimbursable: e.reimbursable,
      reimbursed_status: e.reimbursed_status
    }));
    if (expenses.length === 0) {
      return {
        content: [{ type: "text", text: "No expenses match those filters." }],
        structuredContent: { expenses: [] }
      };
    }
    const total = expenses.reduce((sum, e) => sum + Number(e.amount), 0);
    const text = expenses.map(
      (e) => `${e.date} ${e.merchant} \u2014 ${e.category}, $${Number(e.amount).toFixed(2)} (${e.reimbursed_status})`
    ).join("\n");
    return {
      content: [
        {
          type: "text",
          text: `${expenses.length} expense(s), total $${total.toFixed(2)}:
${text}`
        }
      ],
      structuredContent: { expenses, total }
    };
  }
});

